import {jest} from '@jest/globals';
import {setLogger} from '../../shared/logger.js';
import type {Logger} from '../../shared/logger.js';
import {ToolRegistry} from './registry.js';

describe('ToolRegistry input validation', () => {
  afterEach(() => {
    setLogger(undefined);
  });

  it('rejects an uncompilable static schema when registering its tool', () => {
    const registry = new ToolRegistry();
    let registrationError: unknown;

    try {
      registry.register(
        {
          name: 'broken_weather',
          description: 'Has an invalid JSON Schema type',
          inputSchema: {
            type: 42,
          },
        },
        async () => 'unreachable'
      );
    } catch (error) {
      registrationError = error;
    }

    expect(registrationError).toEqual(
      expect.objectContaining({message: expect.stringMatching(/broken_weather/), cause: expect.any(Error)})
    );
  });

  it('rejects an input missing a required property before invoking the executor', async () => {
    const registry = new ToolRegistry();
    const execute = jest.fn(async () => 'sunny');
    registry.register(
      {
        name: 'weather',
        description: 'Gets weather for a location',
        inputSchema: {
          type: 'object',
          properties: {location: {type: 'string'}},
          required: ['location'],
        },
      },
      execute
    );

    const response = await registry.execute('weather', {});

    expect(execute).not.toHaveBeenCalled();
    expect(response.result).toMatch(/location.*required|required.*location/i);
  });

  it('logs a schema rejection without the invalid input value', async () => {
    const entries: Array<{message: string; fields?: Record<string, unknown>}> = [];
    const record = (_category: string, message: string, fields?: Record<string, unknown>) => {
      entries.push({message, fields});
    };
    const logger: Logger = {debug: record, info: record, warn: record, error: record};
    setLogger(logger);
    const registry = new ToolRegistry();
    registry.register(
      {
        name: 'weather',
        description: 'Gets weather for a location',
        inputSchema: {type: 'object', properties: {location: {type: 'string'}}, required: ['location']},
      },
      async () => 'sunny'
    );

    await registry.execute('weather', {location: 123456789});

    expect({
      validationEntry: entries.some(
        entry => /validation/i.test(entry.message) && /location.*string/i.test(String(entry.fields?.error))
      ),
      includesInvalidValue: JSON.stringify(entries).includes('123456789'),
    }).toEqual({validationEntry: true, includesInvalidValue: false});
  });

  it('passes valid input and undeclared extra properties to the executor unchanged', async () => {
    const registry = new ToolRegistry();
    const input = {location: 'Berlin', units: 'celsius'};
    let executorCalls = 0;
    let receivedInput: Record<string, unknown> | undefined;
    registry.register(
      {
        name: 'weather',
        description: 'Gets weather for a location',
        inputSchema: {type: 'object', properties: {location: {type: 'string'}}, required: ['location']},
      },
      async toolInput => {
        executorCalls += 1;
        receivedInput = toolInput;
        return 'sunny';
      }
    );

    const response = await registry.execute('weather', input);

    expect({executorCalls, receivedInput, response}).toEqual({
      executorCalls: 1,
      receivedInput: input,
      response: {result: 'sunny'},
    });
  });
});
# Tool Input Validation

| Field  | Value                |
| ------ | -------------------- |
| Issue  | re-cinq/HALEngine#37 |
| Status | In Progress          |

Every tool registered in `src/orchestration/tools/registry.ts` declares a JSON Schema `inputSchema` that is forwarded to the configured AI provider, and `ToolRegistry.execute` validates the model-supplied `input` against that schema before calling the tool's executor. When validation fails, `execute` returns a rejection `ToolResponse` describing what was wrong rather than throwing, so the orchestrator feeds the failure back to the model as a `tool_result` within the existing tool-round budget.

## Validation at execute time

- When `input` omits a property listed in `required`, `ToolRegistry.execute` returns a `ToolResponse` whose `result` names the missing property as required and never invokes the executor ([validated by: rejects an input missing a required property before invoking the executor](../../src/orchestration/tools/registry.test.ts#L35), [validated by: rejects input missing a required property with a ToolResponse and never calls the executor](../../src/orchestration/tools/registry.acceptance.test.ts#L16)).
- When `input` supplies a property whose value does not match its declared JSON Schema type, `ToolRegistry.execute` returns a `ToolResponse` naming the failing field path and expected type without invoking the executor, and neither `result` nor the emitted log record contains the offending property value ([validated by: rejects a wrong-typed property naming the field and expected type without leaking the offending value to the result or logs](../../src/orchestration/tools/registry.acceptance.test.ts#L46)).
- A schema rejection is logged with its tool name and the failed property path and constraint, but never the invalid input value ([validated by: logs a schema rejection without the invalid input value](../../src/orchestration/tools/registry.test.ts#L60)).
- When `input` satisfies `required`, declared property types and `enum`, `ToolRegistry.execute` invokes the executor once and passes the input object through unchanged — including undeclared extra properties — without injecting `additionalProperties: false`, coercing types or applying defaults ([validated by: passes valid input and undeclared extra properties to the executor unchanged](../../src/orchestration/tools/registry.test.ts#L87)).
- When `ToolRegistry.execute` is called with a tool name that has not been registered, it throws `Unknown tool: <name>` because an unregistered tool is a programming or configuration error rather than a recoverable input mistake.

## Schema compilation and caching

- A static `ToolDefinition` has its `inputSchema` compiled once at `register` time, so a schema that is not valid JSON Schema throws synchronously from `register` with an error message naming the offending tool and retains the compiler error as its cause ([validated by: rejects an uncompilable static schema when registering its tool](../../src/orchestration/tools/registry.test.ts#L11), [validated by: throws at register time naming the tool when a static inputSchema cannot be compiled](../../src/orchestration/tools/registry.acceptance.test.ts#L94)).
- A static tool's `inputSchema` is compiled at `register` time and reused on every `execute` call without re-reading or re-compiling `definition.inputSchema`.
- A function-valued `ToolDefinitionSource` resolves its definition on each `execute` call and validates against the `inputSchema` returned for that call, caching compiled validators by schema object reference (`WeakMap`) so distinct returned schemas each enforce their own rules.

## Orchestrator tool-loop recovery

- Because a schema rejection returns a `ToolResponse` instead of throwing, `src/orchestration/chatOrchestrator.ts` sends the rejection `result` back to the provider as a `tool_result` message, allowing the model to issue a corrected tool call on the next round and complete the turn within `maxToolRounds` ([validated by: returns a schema rejection as a tool_result in the orchestrator loop so the model can correct the call on the next round](../../src/orchestration/tools/registry.acceptance.test.ts#L112)).
